import React, { useState } from 'react';

export default function Login({ onNavigate, onLoginSuccess }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onLoginSuccess({ name: email.split('@')[0] || 'Admin', role: 'Admin' });
  };

  return (
    <div className="auth-wrapper">
      <div className="glass-card-auth">
        <div className="brand-badge">✦ Smart Inventory Portal</div>
        <div className="auth-header">
          <h1>Welcome Back</h1>
          <p>Sign in to continue to Inventory Portal</p>
        </div>
        
        <form onSubmit={handleSubmit}>
          <div className="input-field-group">
            <label>Email Address</label>
            <input
              type="email"
              className="styled-input"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              placeholder="user@example.com"
            />
          </div>
          
          <div className="input-field-group">
            <label>Password</label>
            <input
              type="password"
              className="styled-input"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              placeholder="••••••••"
            />
          </div>

          <button type="submit" className="btn-glow">Sign In to Portal →</button>
        </form>

        <div className="auth-switch">
          New user?{' '}
          <button type="button" onClick={() => onNavigate('register')}>
            Register
          </button>
        </div>
      </div>
    </div>
  );
}
